import secrets

from django.db import migrations, models


def asignar_codigos(apps, schema_editor):
    """Las cuentas de Cliente que ya existían reciben su código (B-06-001)."""
    Usuario = apps.get_model("accounts", "Usuario")
    usados = set(Usuario.objects.exclude(codigo_cliente=None).values_list("codigo_cliente", flat=True))
    for usuario in Usuario.objects.filter(rol="cliente", codigo_cliente=None):
        codigo = str(secrets.randbelow(900000) + 100000)
        while codigo in usados:
            codigo = str(secrets.randbelow(900000) + 100000)
        usados.add(codigo)
        usuario.codigo_cliente = codigo
        usuario.save(update_fields=["codigo_cliente"])


